import {initModel,setLaugh,snapshotModel} from './model.js';
const $=s=>document.querySelector(s),KIND={place:'地点',person:'人物',purpose:'目的',action:'动作',object:'物品'};
let state={cards:[],facts:[],chat:[],runs:[],scans:[],experiments:[],revision:0,level:100},selected=null,selectedRun=null,filter='active',busy=false,ready=false,toastTimer,factCardId=null,labRunning=false;
const welcome=$('#chat').innerHTML;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6000)}
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
function action(label,fn,cls){const b=el('button',label,cls);b.type='button';b.disabled=busy||!ready;b.onclick=fn;return b}
function selectedCard(){return state.cards.find(c=>c.id===selected)}
function visibleRun(){return state.runs.find(r=>r.id===selectedRun)||state.runs.filter(r=>r.cardId===selected).at(-1)}
async function request(operation,props={}){const r=await fetch('/api/memory-glitch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation,...props,revision:state.revision})});const d=await r.json();if(d.state)state=d.state;if(!r.ok)throw new Error(d.error||'请求失败');return d;}
async function mutate(op,props={},done){if(busy||!ready)return;busy=true;render();try{const d=await request(op,props);if(done)done(d);}catch(e){toast(e.message)}finally{busy=false;render()}}
function renderMemories(){const active=state.cards.filter(c=>!['forgotten','superseded'].includes(c.status)),old=state.cards.filter(c=>['forgotten','superseded'].includes(c.status));$('#active-count').textContent=active.length;$('#forgot-count').textContent=old.length;$('#memory-count').textContent=state.cards.length;$('#context-count').textContent=(state.nextContext?.input.length||0)+' 个字段';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('chosen',b.dataset.filter===filter));const list=$('#memories');list.replaceChildren();const cards=filter==='active'?active:old;if(!cards.length)list.append(el('p','还没有记录。添加自己的记忆，或载入演示。','panel-note'));
 for(const c of cards){const e=el('article',undefined,`memory ${c.status==='keep'?'kept':c.status}`),n=state.facts.filter(f=>f.cardId===c.id&&f.confirmed).length,meta=el('div',undefined,'meta');meta.append(el('span',`MEM ${String(state.cards.indexOf(c)+1).padStart(2,'0')}`),el('span',c.status==='keep'?'◆ KEEP':c.status==='superseded'?'已作废':c.status==='forgotten'?'☾ 已遗忘':`${n} 条已确认事实`));e.append(meta,el('p',c.text));const row=el('div',undefined,'memory-actions');
 if(['forgotten','superseded'].includes(c.status))row.append(action('↩ 恢复',()=>mutate('status',{cardId:c.id,status:'active'})));
 else{row.append(action(c.status==='keep'?'解除 Keep':'Keep',()=>mutate('status',{cardId:c.id,status:c.status==='keep'?'active':'keep'})));for(const [label,status] of [['Forget','forgotten'],['作废','superseded']]){const b=action(label,()=>mutate('status',{cardId:c.id,status}));b.disabled=busy||!ready||c.status==='keep';row.append(b)}}
 const remix=action('Remix ↗',()=>{selected=c.id;selectedRun=null;$('#integrity').value=75;renderRemix();toast('右侧变异室已选择该记忆。')},'remix');remix.disabled=busy||!ready||c.status==='keep';row.append(remix);e.append(row);
 e.append(action(n?'查看 / 编辑事实':'提取事实',()=>openFacts(c.id), 'facts-button'));list.append(e);}
}
function causeLabel(r){if(r.status==='correct')return r.inContext?'精确匹配':'未提供原事实但答对，可能猜中';return r.inContext?'已发送，提取未命中':'该事实未进入本次上下文'}
function detectionCard(d){const box=el('div',undefined,'detection');box.append(el('strong',`外部核对 ${d.correct}/${d.tested} · ${d.score}%`),el('p',`精确匹配 ${d.correct} · 不匹配待复核 ${d.mismatch} · 未知 ${d.unknown}`));const details=el('details');details.append(el('summary','查看检测依据'));for(const r of d.rows){const p=el('p',`${r.question}\n模型：${r.value??'未知'}\n参考：${r.expected}\n${causeLabel(r)}`);details.append(p);}box.append(details);return box;}
function inlineMeme(m,d){const box=el('div',undefined,'inline-meme');box.append(el('span','👻 检测触发 · 以下是虚构 Meme','eyebrow'));const img=el('img');img.alt='幽灵在聊天里出现';const model=snapshotModel();if(model)img.src=model.toDataURL('image/png');else img.hidden=true;box.append(img,el('h3',m.title),el('p',m.caption));const details=el('details');details.append(el('summary','查看虚构故事'),el('p',m.story));box.append(details);
 for(const id of new Set(d.rows.filter(r=>r.cause==='not-provided').map(r=>r.cardId))){const card=state.cards.find(c=>c.id===id);if(card?.status==='forgotten')box.append(action('恢复这条记忆',()=>mutate('status',{cardId:id,status:'active'},()=>toast('已恢复，下一次回答会重新使用这条记忆。'))));}
 if(d.rows.some(r=>r.cause==='not-provided')&&state.level<100)box.append(action('切回完整上下文',()=>mutate('level',{level:100})));
 box.append(el('small','事实缺失和创作是两步独立处理；Meme 不会成为事实。'));return box;}
function renderChat(){const chat=$('#chat');chat.replaceChildren();if(!state.chat.length){chat.innerHTML=welcome;$('#ask-example').onclick=async()=>{if(!state.facts.length)await mutate('seed');send('预算是多少？')};return;}
 setLaugh(state.chat.some(c=>c.meme));for(const c of state.chat){const box=el('div',undefined,`bubble ${c.role}`);box.append(el('span',c.role==='user'?'YOU':'MEMORY GLITCH · AI','role'),el('span',c.text));if(c.role==='user'){box.append(action('＋ 保存为记忆',()=>mutate('add',{text:c.text}),'save-message'));}else if(c.detection){box.append(detectionCard(c.detection));if(c.meme)box.append(inlineMeme(c.meme,c.detection));if(c.memeError)box.append(el('p',`检测已完成；Meme 生成失败：${c.memeError}`,'error'));}else box.append(el('small','本条未匹配已确认事实，未进行回忆评分。','not-tested'));chat.append(box)}chat.scrollTop=chat.scrollHeight;}
function renderRemix(){const c=selectedCard(),r=visibleRun();$('#forget').disabled=busy||!ready||!c||c.status==='keep';$('#forget').textContent=busy?'正在处理…':r?'👻 继续删除字段并变异':'👻 遗忘并变异';$('#integrity').disabled=busy;$('#integrity-label').textContent=$('#integrity').value+'%';$('#remix-source').textContent=c?`${r?'从上轮结构化故事继续':'选中'} · ${(r?.story||c.text).slice(0,28)}`:'选择记忆可继续使用独立变异室';$('#meme-level').textContent=`FIELDS / ${r?.level??100}%`;$('#meme-title').textContent=r?.title||'聊天断片，幽灵上线。';$('#meme-caption').textContent=r?.caption||'右侧是手动创作；自动 Meme 会出现在聊天中。';$('#download').disabled=!r||busy;$('#reveal').disabled=!r||busy;setLaugh(!!r||state.chat.some(c=>c.meme));}
function renderTimeline(){const t=$('#timeline');t.replaceChildren();$('#timeline-count').textContent=state.runs.length+' 次手动变异';if(!state.runs.length){t.append(el('p','手动变异记录在这里；自动触发的 Meme 留在对应聊天回复里。','timeline-empty'));return;}for(const [i,r] of state.runs.entries()){const b=action('',()=>{selected=r.cardId;selectedRun=r.id;renderRemix();renderTimeline()},`evolution ${visibleRun()?.id===r.id?'selected':''}`);b.append(el('small',`GLITCH ${i+1} / ${r.level}%`),el('h3',r.title),el('p',r.story),el('span',`保留 ${r.remaining.length} 个字段 · 删除 ${(r.removedKinds||[]).map(k=>KIND[k]).join('、')||'无'}`));t.append(b)}}
function renderMonitor(){const d=state.chat.filter(c=>c.detection).at(-1)?.detection||state.scans.at(-1);$('#monitor-summary').textContent=d?`本次回忆 ${d.correct}/${d.tested} (${d.score}%) · 不匹配待复核 ${d.mismatch} · 未知 ${d.unknown}`:`已确认 ${state.facts.filter(f=>f.confirmed).length} 条事实 · 尚未检测`;$('#context-level').value=state.level;$('#context-level').disabled=busy||!ready;$('#scan').disabled=busy||!ready;$('#lab-open').disabled=busy||!ready;}
function render(){renderMemories();renderChat();renderRemix();renderTimeline();renderMonitor();$('#send').disabled=busy||!ready;$('#example').disabled=busy||!ready||state.cards.some(c=>c.source==='fixture');$('#add-memory').disabled=busy||!ready||state.cards.length>=60;}
async function send(message){const value=message.trim();if(!value||busy||!ready)return;busy=true;render();$('#chat').append(el('div',value,'bubble user'),el('div','Netlify 正在组装上下文、核对事实…','bubble pending'));$('#chat').scrollTop=$('#chat').scrollHeight;try{await request('chat',{message:value});$('#message').value='';}catch(e){toast(e.message)}finally{busy=false;render();}}
$('#chat-form').onsubmit=e=>{e.preventDefault();send($('#message').value)};$('#message').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send($('#message').value)}};
$('#example').onclick=()=>mutate('seed');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderMemories()});$('#add-memory').onclick=()=>$('#memory-dialog').showModal();$('#save-memory').onclick=()=>{const value=$('#memory-input').value.trim();if(!value)return;$('#memory-dialog').close();mutate('add',{text:value},()=>$('#memory-input').value='')};
$('#context-level').onchange=e=>mutate('level',{level:Number(e.target.value)});$('#scan').onclick=()=>mutate('scan',{},()=>{renderScan(state.scans.at(-1));$('#scan-dialog').showModal()});
function renderScan(d){const node=$('#scan-results');node.replaceChildren(detectionCard(d));const p=el('p','不匹配需要核对别名、提问歧义或模型错误，不能直接叫做“内部遗忘”。');node.append(p);}
$('#integrity').oninput=()=>$('#integrity-label').textContent=$('#integrity').value+'%';$('#forget').onclick=()=>mutate('remix',{cardId:selected,parentId:visibleRun()?.id||null,level:Number($('#integrity').value)},d=>{selectedRun=d.runId;$('#integrity').value=Math.max(0,Number($('#integrity').value)-25)});
$('#context-toggle').onclick=()=>{$('#next-context').textContent=JSON.stringify(state.nextContext,null,2);$('#last-request').textContent=JSON.stringify(state.lastAudit||'尚无请求',null,2);$('#context-dialog').showModal()};$('#help').onclick=()=>$('#help-dialog').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#reveal').onclick=()=>{$('#original').textContent=selectedCard()?.text||'';$('#mutated').textContent=visibleRun()?.story||'';$('#reveal-dialog').showModal()};
function fieldEditor(f={kind:'object',label:'',value:'',question:'',cues:[]}){const row=el('div',undefined,'fact-editor'),kind=el('select');kind.setAttribute('aria-label','字段类型');for(const [key,value]of Object.entries(KIND)){const o=el('option',value);o.value=key;kind.append(o)}kind.value=f.kind;kind.dataset.key='kind';row.append(kind);for(const [key,label]of [['label','标签'],['value','标准答案（原文片段）'],['question','检测问题（不含答案）'],['cues','匹配聊天的关键词，逗号分隔']]){const l=el('label',label),input=el('input');input.value=key==='cues'?(f.cues||[]).join(','):f[key]||'';input.dataset.key=key;l.append(input);row.append(l)}const remove=el('button','移除');remove.onclick=()=>row.remove();row.append(remove);return row;}
async function openFacts(id){factCardId=id;const facts=state.facts.filter(f=>f.cardId===id);if(!facts.length){await mutate('extract',{cardId:id})}const c=state.cards.find(c=>c.id===id);$('#fact-source').textContent=c.text;$('#fact-fields').replaceChildren(...(facts.length?facts.map(f=>({...f,value:f.answer})):c.candidates||[]).map(fieldEditor));if(!$('#fact-fields').children.length)$('#fact-fields').append(fieldEditor());$('#facts-dialog').showModal()}
$('#fact-add').onclick=()=>{if($('#fact-fields').children.length<5)$('#fact-fields').append(fieldEditor())};$('#fact-confirm').onclick=()=>{const fields=[...$('#fact-fields').children].map(row=>Object.fromEntries([...row.querySelectorAll('[data-key]')].map(input=>[input.dataset.key,input.dataset.key==='cues'?input.value.split(/[,，]/).map(s=>s.trim()).filter(Boolean):input.value])));mutate('confirm',{cardId:factCardId,fields},()=>$('#facts-dialog').close())};
function renderLab(){const rows=state.experiments,summary=[100,75,50,25,0].map(level=>{const values=rows.filter(r=>r.level===level),ratings=values.filter(v=>v.creativity!==null);return {level,n:values.length,score:values.length?values.reduce((n,r)=>n+r.score,0)/values.length:null,rating:ratings.length?ratings.reduce((n,r)=>n+r.creativity,0)/ratings.length:null}});const chart=$('#lab-chart');chart.replaceChildren();for(const s of summary){const row=el('div',undefined,'lab-bar');row.append(el('span',`输入 ${s.level}%`));const bar=el('div',undefined,'bar-track'),fill=el('i');fill.style.width=(s.score||0)+'%';bar.append(fill);row.append(bar,el('b',s.score===null?'—':`${s.score.toFixed(1)}%`),el('small',`n=${s.n} · 创造性 ${s.rating===null?'待人工评分':s.rating.toFixed(1)+'/5'}`));chart.append(row)}const list=$('#lab-results');list.replaceChildren();for(const r of rows){const details=el('details');details.append(el('summary',`${r.level}% · 第${r.repeat}次 · 回忆${r.correct}/${r.tested} · 未知${r.unknown} · 不匹配${r.mismatch}`));if(r.meme){details.append(el('h3',r.meme.title),el('p',r.meme.story));const rate=el('select');rate.setAttribute('aria-label',`${r.level}% 第${r.repeat}次 创造性评分`);rate.append(new Option('创造性：请人工评分',''));for(let n=1;n<=5;n++)rate.append(new Option(n+' / 5',String(n)));rate.value=r.creativity??'';rate.onchange=()=>mutate('rate',{id:r.id,rating:Number(rate.value)},renderLab);details.append(rate)}const pre=el('pre',JSON.stringify(r.rows,null,2));details.append(pre);list.append(details)}$('#lab-run').disabled=labRunning||busy||!ready;}
$('#lab-open').onclick=()=>{renderLab();$('#lab-dialog').showModal()};$('#lab-run').onclick=async()=>{if(busy||!ready||labRunning)return;labRunning=true;busy=true;render();let completed=0;try{for(const level of [100,75,50,25,0])for(let repeat=1;repeat<=3;repeat++){if(state.experiments.some(e=>e.level===level&&e.repeat===repeat)){completed++;continue;}$('#lab-progress').textContent=`运行 ${level}% / 第 ${repeat} 次（${completed}/15）…`;await request('experiment',{level,repeat});completed++;renderLab();}$('#lab-progress').textContent='15 次实验完成。回忆曲线为实测，创造性等待你的评分。';}catch(e){$('#lab-progress').textContent='实验暂停：'+e.message+'。再次运行将从未完成项继续。';}finally{labRunning=false;busy=false;render();renderLab()}};
$('#lab-export').onclick=()=>{const data={schema:2,model:'gpt-4.1-mini',note:'Recall is exact-match performance on tested synthetic facts, not memory capacity. Creativity is human-rated; null means not rated.',experiments:state.experiments};const serialized=JSON.stringify(data,null,2);$('#lab-json').value=serialized;$('#lab-export-preview').hidden=false;$('#lab-export-preview').open=true;const blob=new Blob([serialized],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='memory-glitch-experiment.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)};
function wrap(ctx,text,x,y,width,lineHeight){let line='';for(const char of text){if(ctx.measureText(line+char).width>width){ctx.fillText(line,x,y);line=char;y+=lineHeight}else line+=char}ctx.fillText(line,x,y);return y;}
$('#download').onclick=()=>{const r=visibleRun();if(!r)return;const c=document.createElement('canvas');c.width=1080;c.height=1080;const x=c.getContext('2d');x.fillStyle='#181d28';x.fillRect(0,0,1080,1080);const g=x.createRadialGradient(540,410,10,540,410,520);g.addColorStop(0,'#5d486b');g.addColorStop(1,'#181d28');x.fillStyle=g;x.fillRect(0,0,1080,1080);x.fillStyle='#c5b4d8';x.font='24px sans-serif';x.fillText('MEMORY GLITCH / HALLOWEEN LAB',65,70);x.textAlign='right';x.fillText(`${r.level}%`,1015,70);x.textAlign='center';const model=snapshotModel();if(model){const h=510,w=h*model.width/model.height;x.drawImage(model,(1080-w)/2,110,w,h)}else{x.font='240px sans-serif';x.fillText('👻',540,480)}x.fillStyle='#f8f6ea';x.font='bold 58px sans-serif';let y=wrap(x,r.title,540,695,940,72);x.fillStyle='#d5c4e4';x.font='34px sans-serif';wrap(x,r.caption,540,y+70,940,48);x.font='21px sans-serif';x.fillStyle='#a89bba';x.fillText('AI 虚构重构 · 不是真实回忆',540,1005);const url=c.toDataURL('image/png');$('#export-image').src=url;$('#export-link').href=url;$('#export-dialog').showModal();toast('PNG 已生成，可预览并保存。')};render();initModel().then(()=>{renderRemix();renderChat()});
fetch('/api/memory-glitch').then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.error);state=d.state;ready=d.configured;$('#connection').textContent=ready?'Netlify Blobs + AI · 已连接':'AI Gateway 未配置';$('#connection').classList.toggle('ready',ready);render()}).catch(e=>{$('#connection').textContent='连接失败';toast(e.message);render()});
